-- ----------------------------
-- Table structure for ps_album
-- ----------------------------
DROP TABLE IF EXISTS `ps_album`;
CREATE TABLE `ps_album`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '相册名称',
  `album_date` date NOT NULL COMMENT '相册日期（目录解析）',
  `dir_path` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '目录路径（唯一）',
  `cover_file_id` bigint NULL DEFAULT NULL COMMENT '封面文件ID',
  `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '描述',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '地点',
  `file_count` int NULL DEFAULT 0 COMMENT '文件数量',
  `total_size` bigint NULL DEFAULT 0 COMMENT '总大小',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_dir_path`(`dir_path` ASC) USING BTREE,
  INDEX `idx_album_date`(`album_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '相册表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ps_album
-- ----------------------------

-- ----------------------------
-- Table structure for ps_album_file
-- ----------------------------
DROP TABLE IF EXISTS `ps_album_file`;
CREATE TABLE `ps_album_file`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `album_id` bigint NOT NULL,
  `file_id` bigint NOT NULL,
  `sort_order` int NULL DEFAULT 0 COMMENT '排序',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_album_file`(`album_id` ASC, `file_id` ASC) USING BTREE,
  INDEX `idx_album_id`(`album_id` ASC) USING BTREE,
  INDEX `idx_file_id`(`file_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '相册文件关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ps_album_file
-- ----------------------------

-- ----------------------------
-- Table structure for ps_file
-- ----------------------------
DROP TABLE IF EXISTS `ps_file`;
CREATE TABLE `ps_file`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件名',
  `file_ext` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '扩展名',
  `content_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'MIME类型',
  `file_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '原始路径',
  `thumb_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '缩略图路径',
  `file_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'image / video',
  `file_size` bigint NULL DEFAULT NULL COMMENT '文件大小',
  `width` int NULL DEFAULT NULL COMMENT '宽度',
  `height` int NULL DEFAULT NULL COMMENT '高度',
  `duration` int NULL DEFAULT NULL COMMENT '视频时长（秒）',
  `hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '文件hash（去重）',
  `taken_time` datetime NULL DEFAULT NULL COMMENT '拍摄时间(EXIF)',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `lat` decimal(10, 6) NULL DEFAULT NULL COMMENT '纬度',
  `lng` decimal(10, 6) NULL DEFAULT NULL COMMENT '经度',
  `camera` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '相机型号',
  `status` tinyint NULL DEFAULT 1 COMMENT '1正常 0删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_hash`(`hash` ASC) USING BTREE,
  INDEX `idx_taken_time`(`taken_time` ASC) USING BTREE,
  INDEX `idx_file_type`(`file_type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ps_file
-- ----------------------------

-- ----------------------------
-- Table structure for ps_file_tag
-- ----------------------------
DROP TABLE IF EXISTS `ps_file_tag`;
CREATE TABLE `ps_file_tag`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `file_id` bigint NOT NULL,
  `tag_id` bigint NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_file_tag`(`file_id` ASC, `tag_id` ASC) USING BTREE,
  INDEX `idx_file_id`(`file_id` ASC) USING BTREE,
  INDEX `idx_tag_id`(`tag_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文件标签关系表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ps_file_tag
-- ----------------------------

-- ----------------------------
-- Table structure for ps_tag
-- ----------------------------
DROP TABLE IF EXISTS `ps_tag`;
CREATE TABLE `ps_tag`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tag_name`(`name` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '标签表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ps_tag
-- ----------------------------

-- ----------------------------
-- Table structure for ps_timeline
-- ----------------------------
DROP TABLE IF EXISTS `ps_timeline`;
CREATE TABLE `ps_timeline`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `album_id` bigint NOT NULL,
  `album_date` date NOT NULL,
  `cover_file_id` bigint NULL DEFAULT NULL,
  `file_count` int NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_album_date`(`album_date` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '时间轴缓存表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ps_timeline
-- ----------------------------

-- ----------------------------
-- Table structure for sys_cms_content
-- ----------------------------
DROP TABLE IF EXISTS `sys_cms_content`;
CREATE TABLE `sys_cms_content`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '内容类型',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '摘要',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '正文（HTML）',
  `top` tinyint NULL DEFAULT NULL COMMENT '是否置顶',
  `status` tinyint NULL DEFAULT 0 COMMENT '0-草稿 1-发布',
  `sort` int NULL DEFAULT 0 COMMENT '排序',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `creator` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_type`(`type` ASC) USING BTREE,
  INDEX `idx_title`(`title` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_publish_time`(`publish_time` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '系统内容管理表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_cms_content
-- ----------------------------
INSERT INTO `sys_cms_content` VALUES (7, 'System_Guide', '系统概况', '系统首页概况说明', '<table style=\"width: auto; text-align: start;\"><tbody><tr><th colspan=\"1\" rowspan=\"1\" width=\"68\" style=\"text-align: left;\"><strong>系统名</strong>称</th><th colspan=\"0\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\">h-boot-admin管理系统</th></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\"><strong>版本号</strong></td><td colspan=\"0\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\">v1.0.0</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\"><strong>后端框架</strong></td><td colspan=\"0\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\">Spring Boot 3 + Spring Security 6 + JWT</td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\"><strong>前端框架</strong></td><td colspan=\"0\" rowspan=\"1\" width=\"auto\" style=\"text-align: left;\">Vue3 + Vite + Element Plus +TypeScript + Pinia</td></tr></tbody></table><p><br></p>', 1, 1, 0, '2026-01-01 19:28:35', 'admin', '2026-01-01 19:28:35', '2026-01-01 21:40:03');
INSERT INTO `sys_cms_content` VALUES (8, 'Update_Log', '2026-1-1', '2026-1-1更新', '<p>1、修改文章CSM bug</p><p>2、修改文件上传 bug</p>', 0, 1, 1, '2026-01-01 21:30:22', 'admin', '2026-01-01 21:30:22', '2026-01-01 22:11:43');

