-- Table structure for yxfxsjb
-- ----------------------------
DROP TABLE IF EXISTS `yxfxsjb`;
CREATE TABLE `yxfxsjb`  (
  `zjbs` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键标识',
  `ypbh` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '样品编号',
  `yplx` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '样品类型',
  `jhdm` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '井号代码',
  `jh` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '井号',
  `qydd` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '取样地点',
  `qysj` datetime(6) NULL DEFAULT NULL COMMENT '取样时间',
  `cwmc` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '取样层位名称',
  `cwhzmc` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '层位汉字名称',
  `cwds` decimal(7, 2) NULL DEFAULT NULL COMMENT '层位顶深',
  `cwdsa` decimal(7, 2) NULL DEFAULT NULL COMMENT '层位底深',
  `jd` decimal(7, 2) NULL DEFAULT NULL COMMENT '距顶',
  `ypsd` decimal(16, 5) NULL DEFAULT NULL COMMENT '样品深度',
  `ypcd` decimal(7, 2) NULL DEFAULT NULL COMMENT '样品长度',
  `tc` decimal(7, 0) NULL DEFAULT NULL COMMENT '筒次',
  `qygg` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '取样规格',
  `yxmc` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '岩性名称',
  `ys` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '颜色',
  `hyjb` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '含油级别',
  `sywd` decimal(4, 0) NULL DEFAULT NULL COMMENT '实验温度',
  `jcsb` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '检测设备',
  `jcyj` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '检测依据',
  `jcff` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '检测方法',
  `sybh` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '实验编号',
  `sydw` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '实验单位',
  `syjsrq` datetime(6) NULL DEFAULT NULL COMMENT '实验结束日期',
  `czstl` decimal(7, 2) NULL DEFAULT NULL COMMENT '垂直渗透率',
  `spstl` decimal(11, 6) NULL DEFAULT NULL COMMENT '水平渗透率',
  `wz` decimal(11, 6) NULL DEFAULT NULL COMMENT '围压',
  `kxyl` decimal(11, 6) NULL DEFAULT NULL COMMENT '孔隙压力',
  `yxkxd` decimal(6, 2) NULL DEFAULT NULL COMMENT '有效孔隙度',
  `zkxd` decimal(9, 4) NULL DEFAULT NULL COMMENT '总孔隙度',
  `smd` decimal(9, 4) NULL DEFAULT NULL COMMENT '视密度',
  `klmd` decimal(9, 4) NULL DEFAULT NULL COMMENT '颗粒密度',
  `hybhd` decimal(5, 0) NULL DEFAULT NULL COMMENT '含油饱和度',
  `hsbhd` decimal(5, 0) NULL DEFAULT NULL COMMENT '含水饱和度',
  `hqbhd` decimal(5, 0) NULL DEFAULT NULL COMMENT '含气饱和度',
  `bz` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `project_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工程ID',
  `cjr` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `cjsj` datetime(6) NULL DEFAULT NULL COMMENT '创建时间',
  `step_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '步骤id',
  `node_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '节点id',
  `drbz` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'local' COMMENT '导入标志 epdc,local',
  `task_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务id',
  PRIMARY KEY (`zjbs`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '岩心分析数据表' ROW_FORMAT = DYNAMIC;

